//! Transactions and the page-key lock queue (core): the store methods behind transaction,
//! transactionDirect and lockPageKeys. The wrapper (`src/core/rust-engine.ts`) builds a second
//! `Brain` on its own one-thread pool (the transaction executor), binds it to a transaction on the
//! engine's brain with `beginTransaction`, runs the callback's calls on it, and ends it with
//! `commitTransaction` or `rollbackTransaction`. Contract: `rust/docs/store/transactions.md`.
//!
//! Built by the core store work; other families do not edit this file.

use gbrain_store::StoreError;
use gbrain_store::transactions::PageKeyHint;
use napi::Env;
use napi::bindgen_prelude::Object;
use napi_derive::napi;
use serde_json::Value;

use crate::store_binding::{Brain, required};

#[napi]
impl Brain {
    /// `beginTransaction(outer, readOnly?)`, on a closed handle: waits for the writer of `outer`'s
    /// brain, opens the write transaction and makes this handle run on it. Resolves `null`.
    /// Rejects `store_closed` when `outer` is closed and `invalid_state` when this handle is open.
    #[napi]
    pub fn begin_transaction<'env>(
        &self,
        env: &'env Env,
        outer: &Brain,
        read_only: Option<bool>,
    ) -> napi::Result<Object<'env>> {
        let store = outer.current();
        self.bind(env, move || {
            store
                .ok_or_else(|| {
                    StoreError::new(gbrain_store::error::STORE_CLOSED, "the brain is not open")
                })?
                .begin_transaction(read_only.unwrap_or(false))
        })
    }

    /// `savepoint()`: opens a savepoint and resolves its depth.
    #[napi]
    pub fn savepoint<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.savepoint())
    }

    /// `releaseSavepoint(depth)`: keeps the innermost savepoint's writes. Resolves `null`.
    #[napi]
    pub fn release_savepoint<'env>(
        &self,
        env: &'env Env,
        depth: u32,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| s.release_savepoint(depth))
    }

    /// `rollbackSavepoint(depth)`: drops the innermost savepoint's writes. Resolves `null`.
    #[napi]
    pub fn rollback_savepoint<'env>(
        &self,
        env: &'env Env,
        depth: u32,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| s.rollback_savepoint(depth))
    }

    /// `setTransactionReadOnly()`: `SET TRANSACTION READ ONLY`; every later write in the
    /// transaction rejects `read_only_transaction`. Resolves `null`.
    #[napi]
    pub fn set_transaction_read_only<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.set_transaction_read_only())
    }

    /// `commitTransaction()`: commits and resolves the commit's position `{ sequence, index }`
    /// (I-2; `index` is 0 on the single-writer store, and a transaction opened read-only resolves
    /// the end of the batch it saw).
    #[napi]
    pub fn commit_transaction<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.commit_transaction_at())
    }

    /// `rollbackTransaction()`: rolls back (a no-op once ended). Resolves `null`.
    #[napi]
    pub fn rollback_transaction<'env>(&self, env: &'env Env) -> napi::Result<Object<'env>> {
        self.run(env, |s| s.rollback_transaction())
    }

    /// `holdPageKeys(keys, hinted)`: `lockPageKeys` inside the transaction. Resolves every held
    /// key as `[sourceId, slug]`, sorted.
    #[napi]
    pub fn hold_page_keys<'env>(
        &self,
        env: &'env Env,
        keys: Value,
        hinted: bool,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let keys: Vec<PageKeyHint> = required(keys, "holdPageKeys keys")?;
            s.hold_page_keys(&keys, hinted)
        })
    }
}
